import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/DISPLAY.md","filePath":"manual-en/DISPLAY.md","lastUpdated":1785684581000}'),s={name:"manual-en/DISPLAY.md"};function o(d,e,l,n,p,c){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h3 id="_11-1-display" tabindex="-1">11.1 DISPLAY <a class="header-anchor" href="#_11-1-display" aria-label="Permalink to &quot;11.1 DISPLAY&quot;">​</a></h3><p>The <code>DISPLAY</code> command displays information about the variables in the active dataset. A variety of different forms of information can be requested. By default, all variables in the active dataset are displayed. However you can select variables of interest using the <code>/VARIABLES</code> subcommand.</p><pre><code>DISPLAY [SORTED] NAMES [[/VARIABLES=]var_list].
DISPLAY [SORTED] INDEX [[/VARIABLES=]var_list].
DISPLAY [SORTED] LABELS [[/VARIABLES=]var_list].
DISPLAY [SORTED] VARIABLES [[/VARIABLES=]var_list].
DISPLAY [SORTED] DICTIONARY [[/VARIABLES=]var_list].
DISPLAY [SORTED] SCRATCH [[/VARIABLES=]var_list].
DISPLAY [SORTED] ATTRIBUTES [[/VARIABLES=]var_list].
DISPLAY [SORTED] @ATTRIBUTES [[/VARIABLES=]var_list].
DISPLAY [SORTED] VECTORS.
</code></pre><p>The following keywords primarily cause information about variables to be displayed. With these keywords, by default information is displayed about all variable in the active dataset, in the order that variables occur in the active dataset dictionary. The <code>SORTED</code> keyword causes output to be sorted alphabetically by variable name.</p><p>NAMES</p><p>The variables’ names are displayed.</p><p>INDEX</p><p>The variables’ names are displayed along with a value describing their position within the active dataset dictionary.</p><p>LABELS</p><p>Variable names, positions, and variable labels are displayed.</p><p>VARIABLES</p><p>Variable names, positions, print and write formats, and missing values are displayed.</p><p>DICTIONARY</p><p>Variable names, positions, print and write formats, missing values, variable labels, and value labels are displayed.</p><p>SCRATCH</p><p>Variable names are displayed, for scratch variables only (see <a href="./Scratch-Variables">Scratch Variables</a>).</p><p>ATTRIBUTES @ATTRIBUTES</p><p>Datafile and variable attributes are displayed. The first form of the command omits those attributes whose names begin with <code>@</code> or <code>$@</code>. In the second for, all datafile and variable attributes are displayed.</p><p>With the <code>VECTOR</code> keyword, <code>DISPLAY</code> lists all the currently declared vectors. If the <code>SORTED</code> keyword is given, the vectors are listed in alphabetical order; otherwise, they are listed in textual order of definition within the PSPP syntax file.</p><p>For related commands, see <a href="./DISPLAY-DOCUMENTS">DISPLAY DOCUMENTS</a> and <a href="./DISPLAY-FILE-LABEL">DISPLAY FILE LABEL</a>.</p>`,20)])])}const h=a(s,[["render",o]]);export{A as __pageData,h as default};
